mapper.select:
SELECT session_id
FROM member_refresh_token
WHERE token_hash = #{tokenHash}

mapper.insert:
INSERT INTO member_auth_session (
session_id,
member_id,
expires_at_ms
)
VALUES (
#{sessionId},
#{memberId},
#{expiresAtMs}
)

INSERT INTO member_refresh_token (
token_hash,
session_id
)
VALUES (
#{tokenHash},
#{sessionId}
)

mapper.select:
SELECT COUNT(*)
FROM member_auth_session s
INNER JOIN members m
ON m.member_id = s.member_id
WHERE s.session_id = #{sessionId}
AND s.member_id = #{memberId}
AND s.expires_at_ms > #{nowMs}
AND s.revoked_at IS NULL
AND m.account_status = 'ACTIVE'
AND m.deleted_at IS NULL
AND m.system_role = #{systemRole}
